<?php include __DIR__.'/../layouts/header.php';?><div class="toolbar"><div><h1 class="page-title">Estudiantes</h1><p class="subtitle">Gestión de estudiantes y sus datos académicos.</p></div><a class="btn btn-primary" href="/controllers/estudiantes.php?accion=crear">+ Nuevo estudiante</a></div><div class="card"><div class="card-body"><input class="search" data-search="#tablaEstudiantes" placeholder="Buscar estudiante..."><div class="table-wrap"><table class="table" id="tablaEstudiantes"><thead><tr><th>Estudiante</th><th>Correo</th><th>Carrera</th><th>Semestre</th><th>Registro</th><th>Acciones</th></tr></thead><tbody><?php foreach($registros as $r):?><tr><td><strong><?=e($r['nombre'].' '.$r['apellido'])?></strong><br><small><?=e($r['usuario'])?></small></td><td><?=e($r['correo'])?></td><td><?=e($r['nombre_carrera'])?></td><td><?=e($r['semestre'])?></td><td><?=e($r['registro_universitario'])?></td><td><div class="actions"><a class="btn btn-light btn-sm" href="?accion=editar&id=<?=$r['id_estudiante']?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar estudiante y su usuario?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=$r['id_estudiante']?>"><button class="btn btn-danger btn-sm">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div></div><?php if($accion!=='listar'):?><div class="card" style="margin-top:18px"><div class="card-body"><h2 style="margin-top:0"><?= $registro?'Editar':'Nuevo'?> estudiante</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="guardar"><div class="grid grid-2"><div class="form-group"><label class="form-label">Nombre</label><input required name="nombre" value="<?=e($registro['nombre']??'')?>"></div><div class="form-group"><label class="form-label">Apellido</label><input required name="apellido" value="<?=e($registro['apellido']??'')?>"></div><div class="form-group"><label class="form-label">Correo</label><input required type="email" name="correo" value="<?=e($registro['correo']??'')?>"></div><div class="form-group"><label class="form-label">Usuario</label><input required name="usuario" value="<?=e($registro['usuario']??'')?>"></div><?php if(!$registro):?><div class="form-group"><label class="form-label">Contraseña inicial</label><input required type="password" name="clave" value="password"><div class="form-help">Se almacena con password_hash.</div></div><?php endif;?><div class="form-group"><label class="form-label">Teléfono</label><input name="telefono"></div><div class="form-group"><label class="form-label">Carrera</label><select required name="id_carrera"><?php require_once __DIR__.'/../../models/CarreraModel.php';foreach((new CarreraModel($pdo))->obtenerTodas() as $c):?><option value="<?=$c['id_carrera']?>" <?=($registro['id_carrera']??'')==$c['id_carrera']?'selected':''?>><?=e($c['nombre_carrera'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Semestre</label><input required type="number" min="1" max="20" name="semestre" value="<?=e($registro['semestre']??1)?>"></div><div class="form-group"><label class="form-label">Registro universitario</label><input name="registro_universitario" value="<?=e($registro['registro_universitario']??'')?>"></div></div><div class="actions"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="/controllers/estudiantes.php">Cancelar</a></div></form></div></div><?php endif;?><?php include __DIR__.'/../layouts/footer.php';?>
